(7403341, 1164176, 97225, '<td valign="top">Wow! That is beautiful!</td>', 'Wow! That is beautiful!', '2015-09-08 00:06:03.000000', NULL, 1),
(7403342, 1165645, 97225, '<td valign="top">So lovely!</td>', 'So lovely!', '2015-09-08 00:07:41.000000', NULL, 1),
(7403343, 1165106, 173844, '<td valign="top">Fine portrait of a man who certainly has experienced more than I can fathom, who has the steady eye of character and integrity -  at least as I see it.  I wish him well.</td>', 'Fine portrait of a man who certainly has experienced more than I can fathom, who has the steady eye of character and integrity -  at least as I see it.  I wish him well.', '2015-09-08 00:08:12.000000', NULL, 1),
